34	func (d *DB) ListMemoRelations(ctx context.Context, find *store.FindMemoRelation) ([]*store.MemoRelation, error) {
35		where, args := []string{"TRUE"}, []any{}
36		if find.MemoID != nil {
37			where, args = append(where, "`memo_id` = ?"), append(args, *find.MemoID)
38		}
39		if find.RelatedMemoID != nil {
40			where, args = append(where, "`related_memo_id` = ?"), append(args, *find.RelatedMemoID)
41		}
42		if find.Type != nil {
43			where, args = append(where, "`type` = ?"), append(args, *find.Type)
44		}
45		if len(find.MemoIDList) > 0 {
46			placeholders := make([]string, len(find.MemoIDList))
47			for i, id := range find.MemoIDList {
48				placeholders[i] = "?"
49				args = append(args, id)
50			}
51			inClause := strings.Join(placeholders, ", ")
52			for _, id := range find.MemoIDList {
53				args = append(args, id)
54			}
55			where = append(where, fmt.Sprintf("(`memo_id` IN (%s) OR `related_memo_id` IN (%s))", inClause, inClause))
56		}
57		if len(find.SourceMemoIDList) > 0 {
58			placeholders := make([]string, len(find.SourceMemoIDList))
59			for i, id := range find.SourceMemoIDList {
60				placeholders[i] = "?"
61				args = append(args, id)
62			}
63			where = append(where, fmt.Sprintf("`memo_id` IN (%s)", strings.Join(placeholders, ", ")))
64		}
65		if len(find.RelatedMemoIDList) > 0 {
66			placeholders := make([]string, len(find.RelatedMemoIDList))
67			for i, id := range find.RelatedMemoIDList {
68				placeholders[i] = "?"
69				args = append(args, id)
70			}
71			where = append(where, fmt.Sprintf("`related_memo_id` IN (%s)", strings.Join(placeholders, ", ")))
72		}
73		if find.MemoFilter != nil {
74			engine, err := filter.DefaultEngine()
75			if err != nil {
76				return nil, err
77			}
78			stmt, err := engine.CompileToStatement(ctx, *find.MemoFilter, filter.RenderOptions{
79				Dialect:           filter.DialectMySQL,
80				PlaceholderOffset: 0,
81			})
82			if err != nil {
83				return nil, err
84			}
85			if stmt.SQL != "" {
86				where = append(where, fmt.Sprintf("memo_id IN (SELECT id FROM memo WHERE %s)", stmt.SQL))
87				where = append(where, fmt.Sprintf("related_memo_id IN (SELECT id FROM memo WHERE %s)", stmt.SQL))
88				args = append(args, append(stmt.Args, stmt.Args...)...)
89			}
90		}
91	
92		query := "SELECT `memo_id`, `related_memo_id`, `type` FROM `memo_relation` WHERE " + strings.Join(where, " AND ") + " ORDER BY `memo_id` DESC"
93		if find.Limit != nil {
94			query = fmt.Sprintf("%s LIMIT %d", query, *find.Limit)
95			if find.Offset != nil {
96				query = fmt.Sprintf("%s OFFSET %d", query, *find.Offset)
97			}
98		}
99	
100		rows, err := d.db.QueryContext(ctx, query, args...)
101		if err != nil {
102			return nil, err
103		}
104		defer rows.Close()
105	
106		list := []*store.MemoRelation{}
107		for rows.Next() {
108			memoRelation := &store.MemoRelation{}
109			if err := rows.Scan(
110				&memoRelation.MemoID,
111				&memoRelation.RelatedMemoID,
112				&memoRelation.Type,
113			); err != nil {
114				return nil, err
115			}
116			list = append(list, memoRelation)
117		}
118	
119		if err := rows.Err(); err != nil {
120			return nil, err
121		}
122	
123		return list, nil
